package com.nivor.ai;import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="ai_actions",indexes=@Index(name="idx_ai_action_user_status",columnList="user_id,status"))public class AiAction extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="conversation_id",nullable=false)private AiConversation conversation;@Enumerated(EnumType.STRING)@Column(nullable=false,length=32)private AiActionType type;@Column(nullable=false,columnDefinition="TEXT")private String payload;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private AiActionStatus status=AiActionStatus.PROPOSED;private LocalDateTime executedAt;protected AiAction(){}public User getUser(){return user;}public void setUser(User v){user=v;}public AiConversation getConversation(){return conversation;}public void setConversation(AiConversation v){conversation=v;}public AiActionType getType(){return type;}public void setType(AiActionType v){type=v;}public String getPayload(){return payload;}public void setPayload(String v){payload=v;}public AiActionStatus getStatus(){return status;}public void setStatus(AiActionStatus v){status=v;}public LocalDateTime getExecutedAt(){return executedAt;}public void setExecutedAt(LocalDateTime v){executedAt=v;}}
